-- A conversion permanently preserves the selected estimate financial evidence.
SELECT x.id FROM sales_estimateconversion x JOIN sales_estimaterevision r ON r.id=x.revision_id JOIN sales_invoicerevision i ON i.invoice_id=x.invoice_id AND i.number=1 WHERE (json_remove(i.data,'$.id','$.number','$.actor_name','$.state','$.action','$.reason','$.date','$.expiry','$.due_date','$.journal_id','$.reversal_id','$.review_digest') IS NOT json_remove(r.data,'$.id','$.number','$.actor_name','$.state','$.action','$.reason','$.date','$.expiry','$.due_date','$.journal_id','$.reversal_id','$.review_digest') OR (SELECT json_group_array(json_remove(l.data,'$.origin_position','$.origin_revision_id')) FROM (SELECT data FROM sales_invoiceline WHERE revision_id=i.id ORDER BY position) l) IS NOT (SELECT json_group_array(json_remove(l.data,'$.origin_position','$.origin_revision_id')) FROM (SELECT data FROM sales_estimateline WHERE revision_id=r.id ORDER BY position) l));
